function field(label,name,value='',{type='text',max=1000,required=false,hint='',wide=false}={}){return `<label class="field ${wide?'span-two':''}"><span>${esc(label)}</span>${type==='textarea'?`<textarea name="${name}" maxlength="${max}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" maxlength="${max}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}>`}${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
