function syncStatus(){const el=$('#save-status');if(!el||!adapter?.status||!access.canView)return;let s;try{s=adapter.status();}catch{return;}const state=!s.online?'offline':s.pending?'saving':'saved',text={offline:'Sin conexión — se guardará al volver',saving:'Guardando…',saved:'Guardado'}[state];if(el.textContent!==text)el.textContent=text;el.dataset.sync=state;const err=s.lastError?String(s.lastError.message||s.lastError):'';el.title=err?`Último error: ${err}. Se reintentará solo.`:'Sincronizado con tu equipo';}
