function prune(s){const ids=new Set(s.leads.map(l=>l.id));s.tasks=s.tasks.filter(t=>!t.leadId||ids.has(t.leadId));s.conversations=s.conversations.filter(c=>ids.has(c.leadId));}
function denyReadOnly(silent=false){if(access.canEdit)return false;if(!silent)toast(access.guest?'Modo invitado: solo lectura. Entra con tu cuenta para guardar cambios.':'Tu rol puede ver el CRM pero no modificarlo.',true);return true;}
function commit(action,mutate,detail='',silent=false){
 if(denyReadOnly(silent))return false;
 try{state=store.commit(action,s=>{const snap=snapshot(s),n0=s.leads.length;mutate(s);if(s.leads.length!==n0)prune(s);reconcileEnrollments(s,snap);},detail);auditLog(action,detail);render();crm.refreshFicha();if(!silent)toast(remote?'Cambios guardados.':'Cambios guardados en este navegador.');return true;}catch(error){$('#save-status').textContent='No se pudo guardar';toast(error.message,true);return false;}}
