 recompute();
 const [eyebrow,title,subtitle,crumb]=sections[view];if(remote)syncStatus();else{const bk=crm.backupStatus();$('#save-status').textContent=bk.pending&&bk.due?'Respaldo pendiente':'Guardado en este navegador';$('#save-status').title=bk.text;}$('#banner').innerHTML=accessBanner()+teamCopy(crm.bannerHTML());$('#eyebrow').textContent=eyebrow;$('#title').innerHTML=title;$('#subtitle').textContent=subtitle;$('#crumb').textContent=crumb;$$('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});$('#head-actions').innerHTML=headActions();refreshBadges();renderScopeBox();
 ({overview:renderOverview,crm:renderCRM,tasks:UT.render,quotes:UQ.render,properties:UP.render,inbox:UM.render,reports:UR.render,calendar:renderCalendar,usage:renderUsage,heatmap:renderHeatmap,activity:renderActivity,settings:renderSettings}[view])();
