function renderScopeBox(){const slot=$('#scope-slot');if(!slot)return;
 if(access.mode==='user'&&access.user.role==='owner')slot.innerHTML=`<label class="scope"><span class="sr-only">Contactos a mostrar</span><select id="scope-pick" aria-label="Contactos a mostrar"><option value="all" ${access.scope==='all'?'selected':''}>Todos los contactos</option><option value="mine" ${access.scope==='mine'?'selected':''}>Mis contactos</option></select></label>`;
 else if(access.mode==='user'&&access.scope==='mine')slot.innerHTML='<span class="scope-pill">Mis contactos</span>';else slot.innerHTML='';}
function refreshBadges(){try{const st=scoped(),n=newFromSite(st.leads),tc=taskCounts(st.tasks,new Date(),{hidden:hiddenTaskIds(st.tasks,st.enrollments)});const set=(id,v,label)=>{const el=$(id);if(!el)return;el.hidden=!v;el.textContent=v?String(v):'';if(label)el.title=label;};set('#badge-crm',n,`${n} nuevos del sitio`);set('#badge-tasks',tc.overdue+tc.today,`${tc.overdue} vencidas · ${tc.today} para hoy`);}catch{}}
// ───────── acceso, alcance y datos compartidos ─────────
function isMine(l){const me=fold(access.user.name),em=fold(access.user.email),o=fold(l.owner);return !!o&&(o===me||o===em);}
function scoped(){
 if(access.scope!=='mine')return state;
 const key=access.user.name+'|'+access.user.email;if(scopeMemo.state===state&&scopeMemo.key===key)return scopeMemo.val;
 const mine=new Set(),leads=state.leads.filter(l=>{const ok=isMine(l);if(ok)mine.add(l.id);return ok;});
 const val={...state,leads,tasks:state.tasks.filter(t=>t.leadId?mine.has(t.leadId):fold(t.owner)===fold(access.user.name)),quotes:state.quotes.filter(q=>mine.has(q.leadId)),conversations:state.conversations.filter(c=>mine.has(c.leadId)),enrollments:state.enrollments.filter(e=>mine.has(e.leadId))};
 scopeMemo={state,key,val};return val;}
function computeAccess(){
 if(remote){const p=remote.profile||{},sess={user:{name:p.name||p.email||'',email:p.email||'',role:p.role||''}},can=a=>{try{return !!dataLayer?.can(a,sess);}catch{return false;}},role=sess.user.role,canView=can('crm.view');
  access={mode:canView?'user':'denied',canView,canEdit:can('crm.edit'),scope:role==='sales'?'mine':(role==='owner'&&ss.get(SCOPE_KEY)==='mine'?'mine':'all'),guest:false,user:sess.user,role:({owner:'Dueño',editor:'Editor',sales:'Vendedor',client:'Cliente'})[role]||role};return;}
 const guest=ss.get(GUEST_KEY)==='1';
 if(!dataLayer){access={mode:'standalone',canView:true,canEdit:true,scope:'all',guest:false,user:{name:'',email:'',role:''},role:''};return;}
 const sess=dataLayer.getSession();
 if(!sess){access=guest?{mode:'guest',canView:true,canEdit:false,scope:'all',guest:true,user:{name:'Invitado',email:'',role:''},role:''}:{mode:'none',canView:false,canEdit:false,scope:'all',guest:false,user:{name:'',email:'',role:''},role:''};return;}
 const u=sess.user,role=u.role,canView=dataLayer.can('crm.view'),canEdit=dataLayer.can('crm.edit');
 const scope=role==='sales'?'mine':(role==='owner'&&ss.get(SCOPE_KEY)==='mine'?'mine':'all');
 access={mode:canView?'user':'denied',canView,canEdit,scope,guest:false,user:{name:u.name,email:u.email,role},role:({owner:'Dueño',editor:'Editor',sales:'Vendedor',client:'Cliente'})[role]||role};}
function canProp(kind){if(!dataLayer||!access.canView)return false;if(access.mode==='guest')return false;try{return dataLayer.can(kind==='edit'?'properties.edit':'properties.status');}catch{return false;}}
function reloadProps(){try{props=dataLayer?dataLayer.properties.list():[];}catch{props=[];}scoreKey=null;}
function owners(){const names=new Set();try{for(const u of dataLayer?.users.list()||[])names.add(u.name);}catch{}for(const l of state.leads)if(l.owner)names.add(l.owner);return [...names].sort((a,b)=>a.localeCompare(b,'es'));}
function recompute(){
 const key=state;if(scoreKey===key)return;scoreKey=key;
 const ctx2=scoreContext({pipelines:state.settings.pipelines,properties:props,conversations:state.conversations,now:new Date()});
 scoreMap=scoreAll(state.leads,state.settings.scoreRules,ctx2);scoreVer++;setScoreGetter(l=>scoreMap.get(l.id)?.total??null);}
function processIntake(){
 if(remote){processIntakeRemote();return;}
 if(!dataLayer||intakeBusy||!access.canEdit)return;let items;try{items=dataLayer.intake.list();}catch{return;}if(!items.length)return;intakeBusy=true;
 try{let res;const ok=commit('Formularios del sitio → contactos',s=>{res=applyIntake(s.leads,items,{pipelines:s.settings.pipelines,properties:props,now:new Date()});s.leads=res.leads;},`${items.length} formulario${items.length===1?'':'s'}`,true);
  if(ok){for(const l of res.links){try{dataLayer.properties.linkLead(l.propertyId,l.leadId,true);}catch{}}try{dataLayer.intake.drain();}catch{}reloadProps();toast(`${res.created.length} contacto${res.created.length===1?'':'s'} nuevo${res.created.length===1?'':'s'} del sitio${res.merged.length?` y ${res.merged.length} actualizado${res.merged.length===1?'':'s'} (ya existían)`:''}.`);render();}}
 catch(e){toast('No se pudieron procesar los formularios: '+e.message,true);}finally{intakeBusy=false;}}
// En la nube varios usuarios pueden tener el panel abierto: primero se reclaman los envíos (drain los marca como procesados) y luego se convierten en contactos; applyIntake une duplicados por correo o teléfono.
async function processIntakeRemote(){
 if(!dataLayer||intakeBusy||!access.canEdit)return;intakeBusy=true;
 try{const pending=await dataLayer.intake.list();if(!pending?.length)return;const items=await dataLayer.intake.drain();if(!items?.length)return;
  let res;const ok=commit('Formularios del sitio → contactos',s=>{res=applyIntake(s.leads,items,{pipelines:s.settings.pipelines,properties:props,now:new Date()});s.leads=res.leads;},`${items.length} formulario${items.length===1?'':'s'}`,true);
  if(!ok){toast(`No se pudieron convertir ${items.length} formulario${items.length===1?'':'s'} en contactos. Siguen registrados en la base de datos.`,true);return;}
  for(const l of res.links){try{const r=dataLayer.properties.linkLead(l.propertyId,l.leadId,true);r?.catch?.(()=>{});}catch{}}
  reloadProps();toast(`${res.created.length} contacto${res.created.length===1?'':'s'} nuevo${res.created.length===1?'':'s'} del sitio${res.merged.length?` y ${res.merged.length} actualizado${res.merged.length===1?'':'s'} (ya existían)`:''}.`);render();}
 catch(e){toast('No se pudieron procesar los formularios: '+e.message,true);}finally{intakeBusy=false;}}
function renderOverview(){const usage=usageSummary(state.usage),scheduled=state.publications.filter(p=>p.status==='scheduled').length;$('#content').innerHTML=`${crm.overviewHTML()}<div class="grid-two"><section class="card"><div class="card-head"><h2>Próximas publicaciones</h2>${button('Abrir agenda ↗','go-calendar','small ghost')}</div>${nextPublications()}<p class="storage-meta">${state.publications.length} publicaciones · ${scheduled} programadas localmente</p></section><section class="card"><div class="card-head"><h2>Consumo de IA registrado</h2>${button('Ver detalle ↗','go-usage','small ghost')}</div><p class="muted">Entrada: <b>${usage.input===null?'Sin datos':fmt.format(usage.input)}</b> · Salida: <b>${usage.output===null?'Sin datos':fmt.format(usage.output)}</b></p><p class="storage-meta">${usage.count} registros declarados o importados. Sin conexión automática con proveedores.</p></section></div><section class="card"><div class="card-head"><h2>Últimos movimientos</h2>${button('Toda la actividad ↗','go-activity','small ghost')}</div>${activityList(state.activity.slice(0,5))}</section>`;}
function nextPublications(){const posts=state.publications.filter(p=>p.scheduledAt).sort((a,b)=>a.scheduledAt.localeCompare(b.scheduledAt)).filter(p=>new Date(p.scheduledAt)>=new Date()).slice(0,4);return posts.length?`<ul class="plain-list">${posts.map(p=>`<li><button class="link-btn" data-action="edit-post" data-id="${esc(p.id)}">${esc(p.title)}</button><p class="muted" style="margin:4px 0">${esc(stamp(p.scheduledAt))} · ${esc(p.channel)}</p>${pill(p.status,POST_STATUSES)}</li>`).join('')}</ul>`:empty('Una agenda con intención','Crea tu primera publicación y define cuándo te gustaría compartirla.');}
const renderCRM=crm.renderCRM;
function renderCalendar(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,last=new Date(y,m+1,0).getDate(),today=new Date().toDateString();let cells='';for(let day=-offset+1;day<=Math.ceil((offset+last)/7)*7-offset;day++){const d=new Date(y,m,day),isCurrent=d.getMonth()===m,posts=state.publications.filter(p=>p.scheduledAt&&new Date(p.scheduledAt).toDateString()===d.toDateString());cells+=`<div class="day ${!isCurrent?'off':''} ${d.toDateString()===today?'today':''}"><span>${d.getDate()}</span>${posts.slice(0,3).map(p=>`<button class="calendar-post" data-action="edit-post" data-id="${esc(p.id)}" title="${esc(p.title)}">${esc(p.title)}</button>`).join('')}${posts.length>3?`<small>+${posts.length-3}</small>`:''}</div>`;}$('#content').innerHTML=`<div class="notice warn">La aprobación y programación son locales. Ninguna publicación se envía a redes sociales: todavía no hay cuentas conectadas.</div><section class="card"><div class="card-head"><h2>${esc(month.toLocaleDateString('es-MX',{month:'long',year:'numeric'}))}</h2><div class="actions">${button('←','month-prev','small','aria-label="Mes anterior"')}${button('Hoy','month-today','small')}${button('→','month-next','small','aria-label="Mes siguiente"')}</div></div><div class="table-wrap"><div class="calendar">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div></div></section>${postsSection()}`;}
function postChannels(){return [...new Set(state.publications.map(p=>p.channel).filter(Boolean))].sort();}
function postsSection(){const o=(v,t,cur)=>`<option value="${esc(v)}" ${cur===v?'selected':''}>${esc(t)}</option>`;
 if(!state.publications.length)return `<section class="card"><div class="card-head"><h2>Todo tu contenido</h2><span>0 publicaciones locales</span></div>${empty('Empieza con una idea','Crea un borrador, revisa su texto y apruébalo antes de programarlo.',button('Crear borrador','new-post','small'))}</section>`;
 return `<section class="card"><div class="card-head"><h2>Todo tu contenido</h2><span id="posts-count" role="status" aria-live="polite"></span></div><div class="toolbar post-filters"><input type="search" id="pf-q" placeholder="Buscar título, copy o hashtags…" aria-label="Buscar publicaciones" value="${esc(postFilters.q)}"><select id="pf-status" aria-label="Estado"><option value="">Todos los estados</option>${Object.entries(POST_STATUSES).map(([k,t])=>o(k,t,postFilters.status)).join('')}</select><select id="pf-channel" aria-label="Canal"><option value="">Todos los canales</option>${postChannels().map(c=>o(c,c,postFilters.channel)).join('')}</select><label class="inline-field"><span>Mes</span><input type="month" id="pf-month" value="${esc(postFilters.month)}"></label><select id="pf-dated" aria-label="Fecha"><option value="">Con y sin fecha</option>${o('with','Solo con fecha',postFilters.dated)}${o('without','Sin fecha',postFilters.dated)}</select><select id="pf-sort" aria-label="Ordenar publicaciones">${Object.entries(POST_SORTS).map(([k,t])=>o(k,t,postFilters.sort)).join('')}</select><button type="button" class="btn small ghost" data-action="clear-post-filters">Limpiar</button></div><div id="post-results">${postResults()}</div></section>`;}
function postResults(){let list;try{list=filterPosts(state.publications,postFilters);}catch{postFilters=defaultPostFilters();list=filterPosts(state.publications,postFilters);}
 setTimeout(()=>{const c=$('#posts-count');if(c)c.textContent=`${list.length} de ${state.publications.length} publicaciones`;},0);
 try{sessionStorage.setItem(POSTS_KEY,JSON.stringify(postFilters));}catch{}
 return list.length?`<div class="table-wrap"><table><thead><tr><th>Publicación</th><th>Canal</th><th>Fecha prevista</th><th>Estado</th><th>Siguiente paso</th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="link-btn" data-action="edit-post" data-id="${esc(p.id)}">${esc(p.title)}</button></td><td>${esc(p.channel)}</td><td>${p.scheduledAt?esc(stamp(p.scheduledAt)):'Sin fecha'}</td><td>${pill(p.status,POST_STATUSES)}</td><td>${postStep(p)}</td></tr>`).join('')}</tbody></table></div>`:empty('Ninguna publicación coincide con estos filtros','Prueba otro estado, canal o mes. Tus publicaciones siguen guardadas.',button('Limpiar filtros','clear-post-filters','small'));}
function postStep(post){const next={draft:['Enviar a revisión','review'],review:['Aprobar localmente','approved'],approved:['Programar localmente','scheduled']}[post.status];return next?button(next[0],'post-status','small',`data-id="${esc(post.id)}" data-next="${next[1]}"`)+(post.status==='review'&&post.calendar?button('Rechazar','reject-post','small danger',`data-id="${esc(post.id)}"`):''):'<span class="muted">Pendiente de conexión</span>';}
function renderInbox(){$('#content').innerHTML=`<div class="notice">No hay cuentas conectadas ni conversaciones importadas. Este demo no solicita contraseñas, no lee mensajes y no envía respuestas.</div><div class="connections">${[['◎','Instagram','Mensajes directos y comentarios'],['◉','WhatsApp Business','Conversaciones con tus prospectos'],['✉','Correo electrónico','Consultas y seguimiento']].map(([icon,name,description])=>`<section class="card connection"><span class="network">${icon}</span><h3>${name}</h3><p class="muted">${description}</p><span class="network-status">○ Sin conectar</span>${button('Ver requisitos de conexión','connection','small',`data-network="${name}"`)}</section>`).join('')}</div><section class="card">${empty('Las conversaciones aparecerán al conectar tus canales','Cada proveedor requiere una integración autorizada. El demo mantiene este espacio vacío para no mostrar chats inventados.')}</section>`;}
function renderUsage(){const sum=usageSummary(state.usage),display=n=>n===null?'Sin datos':fmt.format(n),max=Math.max(1,(sum.frontend.input??0)+(sum.frontend.output??0),(sum.backend.input??0)+(sum.backend.output??0));$('#content').innerHTML=`<div class="stats">${stat('ENTRADA REGISTRADA',display(sum.input),`${sum.unknownInput} registros con entrada desconocida`,true)}${stat('SALIDA REGISTRADA',display(sum.output),`${sum.unknownOutput} registros con salida desconocida`)}${stat('REGISTROS',sum.count,'Manual o importación con procedencia')}${stat('PROVEEDORES CONECTADOS','0','Sin medición automática de APIs')}</div><div class="notice">No estimamos tokens a partir del texto ni del precio de un plan. Solo sumamos valores que tú registras o importas. «Sin datos» significa desconocido; cero solo aparece cuando está registrado.</div><section class="card"><div class="card-head"><h2>Frontend y backend</h2>${button('Importar JSON / CSV','import','small')}</div>${['frontend','backend'].map(scope=>{const total=(sum[scope].input??0)+(sum[scope].output??0);return `<div class="bar-row"><span>${scope==='frontend'?'Frontend':'Backend'}</span><div class="bar"><i style="width:${total/max*100}%"></i></div><b>${sum[scope].input===null&&sum[scope].output===null?'Sin datos':fmt.format(total)}</b></div><p class="storage-meta">${scope==='frontend'?'Frontend':'Backend'}: entrada ${display(sum[scope].input)} · salida ${display(sum[scope].output)}</p>`;}).join('')}</section><section class="card"><div class="card-head"><h2>Consumo registrado</h2><span>Cada registro indica su origen</span></div>${state.usage.length?`<div class="table-wrap"><table><thead><tr><th>Modelo / proveedor</th><th>Origen</th><th>Entrada</th><th>Salida</th><th>Capa</th><th>Fecha</th><th></th></tr></thead><tbody>${state.usage.map(u=>`<tr><td>${esc(u.model)}<small>${esc(u.provider)} ${u.reference?'· '+esc(u.reference):''}</small></td><td><span class="source-label">${esc(({manual:'Declarado manual',csv:'Importado CSV',json:'Importado JSON',instrumented:'Instrumentado'})[u.source])}</span></td><td>${display(u.inputTokens)}</td><td>${display(u.outputTokens)}</td><td>${esc(u.scope)}</td><td>${esc(stamp(u.date))}</td><td>${button('×','delete-usage','small danger',`data-id="${esc(u.id)}" aria-label="Eliminar registro ${esc(u.model)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay consumo registrado','Añade cifras de tus reportes o importa un archivo con eventos frontend y backend.',button('Registrar consumo','new-usage','small'))}</section>`;}
function heatGroups(){return [...new Set(state.events.map(e=>JSON.stringify([e.template,e.page])))];}
function renderHeatmap(){const groups=heatGroups();if(!groups.includes(selectedHeat))selectedHeat=groups[0]||'';const base=state.events.filter(e=>JSON.stringify([e.template,e.page])===selectedHeat),viewports=[...new Set(base.map(e=>`${e.viewportWidth} × ${e.viewportHeight}`))];if(selectedViewport&&!viewports.includes(selectedViewport))selectedViewport='';const events=base.filter(e=>!selectedViewport||`${e.viewportWidth} × ${e.viewportHeight}`===selectedViewport);$('#content').innerHTML=`<section class="card"><div class="card-head"><h2>Captura con consentimiento</h2><span>${state.settings.analyticsConsent?'ACTIVA EN ESTE ORIGEN':'DETENIDA'}</span></div><label class="checkbox"><input type="checkbox" id="analytics-consent" ${state.settings.analyticsConsent?'checked':''}><span>Permitir que este panel guarde eventos técnicos de interacción enviados por páginas ORNAT del mismo origen.<br><small class="muted">Solo coordenadas, página, plantilla, fecha y viewport. No se capturan textos, teclas ni datos de formularios.</small></span></label></section><div class="toolbar"><select id="heat-group" aria-label="Página y plantilla">${groups.length?groups.map(g=>{const [template,page]=JSON.parse(g);return `<option value="${esc(g)}" ${g===selectedHeat?'selected':''}>${esc(template+' · '+page)}</option>`;}).join(''):'<option value="">Sin páginas registradas</option>'}</select><select id="heat-viewport" aria-label="Viewport"><option value="">Todos los viewports</option>${viewports.map(v=>`<option value="${esc(v)}" ${v===selectedViewport?'selected':''}>${esc(v)}</option>`).join('')}</select>${button('Actualizar','refresh-heat','small')}${button('Eliminar eventos','clear-events','small danger')}</div><section class="card"><div class="card-head"><h2>Mapa de coordenadas normalizadas</h2><span>${events.length} eventos reales ${selectedViewport?'· '+selectedViewport:''}</span></div><div class="heat-canvas" aria-label="Mapa de coordenadas de interacción">${events.length?events.map(e=>`<span class="heat-dot" style="left:${Number(e.x)*100}%;top:${e.y*100}%" title="${esc(e.eventType+' · '+stamp(e.timestamp))}"></span>`).join(''):empty('Sin interacciones registradas','Activa el consentimiento y recibe eventos de una página instrumentada. No mostramos un mapa de ejemplo.')}</div><p class="storage-meta" style="margin-top:13px">Las posiciones se expresan respecto al viewport. Este mapa no es una captura de pantalla de la página ni representa desplazamiento vertical acumulado. Filtra por viewport para comparar sesiones del mismo tamaño.</p></section><details class="card"><summary>Formato de integración y datos</summary><p class="muted" style="margin-top:15px">Las páginas del mismo origen pueden enviar eventos por BroadcastChannel «ornat-control-analytics», por postMessage o mediante la clave localStorage «ornat-analytics-events». El panel solo los acepta cuando diste consentimiento. También puedes importar un JSON con formato «ornat-analytics» y una lista events.</p><pre class="code">{channel: "ornat-control", type: "analytics-event", event: {
  page: "/templates/mi-proyecto", template: "mi-proyecto",
  x: 0.25, y: 0.60, viewportWidth: 1440, viewportHeight: 900,
  eventType: "click", timestamp: "fecha ISO"
}}</pre><p class="storage-meta">El ejemplo explica la estructura. No se incluye en tus datos ni en el mapa.</p></details>`;}
function renderActivity(){$('#content').innerHTML=`<section class="card"><div class="card-head"><h2>${remote?'Acciones del equipo':'Acciones en este navegador'}</h2><span>${state.activity.length} registros${remote?'':' locales'}</span></div>${activityList(state.activity)}</section>`;}
function renderSettings(){const bytes=new Blob([JSON.stringify(state)]).size;$('#content').innerHTML=`<div class="grid-two"><section class="card"><div class="card-head"><h2>ORNAT CALENDARIO EDITORIAL</h2><span class="pill">Sincronización manual</span></div><p class="muted">Hoja verificada; sincronización automática pendiente. Importa una copia del calendario para revisar aquí y devuelve un archivo de decisiones a tu hoja privada.</p><a class="btn primary" href="${esc(state.settings.sheetUrl)}" target="_blank" rel="noopener noreferrer">Abrir Google Sheets ↗</a><p class="storage-meta" style="margin-top:14px">1. Descarga el script de integración y vincúlalo desde Extensiones → Apps Script en tu hoja privada.<br>2. Exporta el calendario a JSON desde el menú del script e impórtalo aquí.<br>3. Revisa y aprueba localmente; descarga tus decisiones e impórtalas de vuelta en Sheets.<br>No necesitas publicar la hoja ni desplegar una web app.</p><a class="btn small" href="../integrations/ornat-calendar-apps-script.txt" download>Descargar script para Google Sheets ↗</a><div style="margin-top:12px">${button('Exportar decisiones de revisión','calendar-reviews','small')}</div><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><label class="field"><span>Enlace a la hoja</span><input id="sheet-url" type="url" value="${esc(state.settings.sheetUrl)}"></label>${button('Guardar enlace','save-sheet','small')}<p class="storage-meta" style="margin-top:15px">Para traer datos: en Sheets descarga Archivo → Descargar → Valores separados por comas (.csv), luego elige «Importar datos» y relaciona sus columnas.</p></section><section class="card"><h2>Un respaldo que viaja contigo</h2><p class="muted">Incluye contactos, publicaciones, consumo, eventos y actividad. No contiene credenciales.</p><div class="actions">${button('Descargar respaldo JSON','backup','lime')}${button('Importar JSON / CSV','import')}</div><p class="storage-meta" style="margin-top:20px">${remote?'Datos actuales':'Datos locales actuales'}: ${(bytes/1024).toFixed(1)} KB · ${state.leads.length} contactos · ${state.publications.length} publicaciones · ${state.events.length} eventos.</p><p class="storage-meta">${remote?'Se guardan en la nube de ORNAT y se sincronizan con todo tu equipo.':'El navegador puede borrar estos datos al limpiar su almacenamiento. No hay nube ni sincronización entre dispositivos.'}</p></section></div>${teamCopy(crm.settingsExtras())}<section class="card"><h2>Formatos de importación</h2><ul class="plain-list"><li><b>Contactos CSV:</b> relaciona nombre*, empresa, correo, teléfono, etapa (Nuevo, Contactado, Propuesta, Ganado, Perdido o su clave en inglés), canal, responsable, etiquetas (separadas por | o comas), prioridad, valor MXN, tipo de proyecto, próxima acción y su fecha, último contacto, motivo de pérdida, notas y fecha de alta (AAAA-MM-DD o DD/MM/AAAA). Detectamos duplicados por correo o teléfono. El CSV que exporta el CRM se puede volver a importar.</li><li><b>Publicaciones CSV:</b> título, contenido, canal y fecha ISO. Conserva ID y el estado de la hoja. Aprobados o programados entran en revisión local para que vuelvas a confirmarlos.</li><li><b>Tokens CSV/JSON:</b> fecha, proveedor, modelo, entrada, salida, frontend/backend y referencia. Un campo vacío conserva el valor desconocido.</li><li><b>JSON de consumo:</b> un arreglo de registros o un objeto con records/usage. Acepta inputTokens/outputTokens e input_tokens/output_tokens. El origen se marca «Importado JSON».</li><li><b>Respaldo ORNAT:</b> restaura las listas completas después de tu confirmación.</li></ul></section><section class="card danger-zone"><h2>Empezar de nuevo</h2><p class="muted">Elimina contactos, publicaciones, consumo y eventos de este panel${remote?' para todo el equipo':''}. Descarga un respaldo antes si necesitas conservarlos.</p>${button(remote?'Borrar datos del equipo':'Borrar datos locales','reset','danger')}</section>`;}
function openDialog(kind,title,body,actions,id=''){$('#dialog').dataset.kind=kind;$('#dialog').dataset.id=id;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=teamCopy(body);$('#dialog-actions').innerHTML=actions;if(!$('#dialog').open)$('#dialog').showModal();}
function postDialog(id){const post=state.publications.find(p=>p.id===id)||{title:'',channel:'Instagram',content:'',scheduledAt:'',notes:'',status:'draft'};openDialog('post',id?'Tu publicación':'Una idea para compartir',`<div class="notice">Guardar texto o cambiar la fecha devuelve la publicación a borrador para volver a revisarla. La aprobación no envía contenido a ninguna plataforma.</div><div class="form-grid">${field('Título interno','title',post.title,{required:true,max:200,wide:true})}${select('Canal previsto','channel',post.channel,{Instagram:'Instagram',Facebook:'Facebook',LinkedIn:'LinkedIn',TikTok:'TikTok',Blog:'Blog',Email:'Email',Otro:'Otro'})}${field('Fecha y hora prevista','scheduledAt',post.scheduledAt?localDate(post.scheduledAt):'',{type:'datetime-local'})}${field('Contenido','content',post.content,{type:'textarea',max:30000,wide:true})}${field('Notas de revisión','notes',post.notes,{type:'textarea',max:10000,wide:true})}</div>${pill(post.status,POST_STATUSES)}${post.calendar?`<p class="storage-meta">ID de hoja: ${esc(post.calendar.id)} · Estado original: ${esc(post.calendar.expectedState)}. La revisión conserva la versión importada.</p>`:''}${post.hashtags?`<p class="storage-meta">Hashtags: ${esc(post.hashtags)}</p>`:''}`,`${id?button('Eliminar','delete-post','danger',`data-id="${esc(id)}"`):''}${button('Cancelar','close')}<button class="btn primary" type="submit">Guardar borrador</button>`,id||'');}
function usageDialog(){openDialog('usage','Registrar consumo real',`<p class="token-form-note">Copia cifras de un reporte real. Este registro quedará identificado como <b>declarado manualmente</b>. Deja una cifra vacía si es desconocida. El valor 0 indica cero medido o reportado.</p><div class="form-grid">${field('Proveedor','provider','',{max:100,required:true})}${field('Modelo','model','',{max:150,required:true})}${field('Tokens de entrada','inputTokens','',{type:'number'})}${field('Tokens de salida','outputTokens','',{type:'number'})}${select('Capa de origen','scope','backend',{frontend:'Frontend',backend:'Backend'})}${field('Fecha del consumo','date',localDate(),{type:'datetime-local',required:true})}${field('Referencia del reporte / evento','reference','',{wide:true,max:1000,required:true,hint:'Por ejemplo, nombre del reporte y periodo o identificador del evento. No incluyas claves API.'})}</div>`,`${button('Cancelar','close')}<button class="btn primary" type="submit">Guardar registro declarado</button>`);}
function csvDialog(){const kind=$('#csv-kind')?.value||'leads';const labels={leads:{name:'Nombre *',company:'Empresa',email:'Correo',phone:'Teléfono',status:'Etapa',channel:'Canal',owner:'Responsable',tags:'Etiquetas',priority:'Prioridad',value:'Valor (MXN)',projectType:'Tipo de proyecto',nextAction:'Próxima acción',nextActionAt:'Fecha de próxima acción',lastContactAt:'Último contacto',lostReason:'Motivo de pérdida',createdAt:'Fecha de alta',notes:'Notas'},publications:{sheetId:'ID de fila en Sheets',title:'Título *',content:'Copy / contenido',channel:'Red / canal',format:'Formato',scheduledDate:'Fecha (Cancún)',scheduledTime:'Hora (Cancún)',scheduledAt:'Fecha/hora ISO completa (opcional)',hashtags:'Hashtags',asset:'Archivo',sheetStatus:'Estado original en la hoja',notes:'Notas'},usage:{date:'Fecha ISO',provider:'Proveedor',model:'Modelo',inputTokens:'Tokens entrada',outputTokens:'Tokens salida',scope:'frontend / backend'}};const aliases={name:['Nombre','Name'],company:['Empresa','Company'],email:['Correo','Email'],phone:['Teléfono','Telefono','Phone'],status:['Etapa','Status'],notes:['Notas','Notes'],channel:['Canal','Origen','Channel'],owner:['Responsable','Owner'],tags:['Etiquetas','Tags'],priority:['Prioridad','Priority'],value:['Valor MXN','Valor','Value'],projectType:['Tipo de proyecto','Proyecto'],nextAction:['Próxima acción','Proxima accion'],nextActionAt:['Fecha próxima acción','Fecha de seguimiento'],lastContactAt:['Último contacto','Ultimo contacto'],lostReason:['Motivo de pérdida','Motivo'],createdAt:['Creado','Fecha de alta'],sheetId:['ID'],title:['Título','Titulo','Title'],content:['Copy','Contenido','Content'],channel:['Red','Canal','Channel'],format:['Formato','Format'],scheduledDate:['Fecha'],scheduledTime:['Hora'],hashtags:['Hashtags'],asset:['Archivo'],sheetStatus:['Estado'],date:['Fecha','Date'],provider:['Proveedor','Provider'],model:['Modelo','Model'],inputTokens:['inputTokens','input_tokens','Entrada'],outputTokens:['outputTokens','output_tokens','Salida'],scope:['Capa','Scope']};openDialog('csv','Relaciona tus columnas',`<p class="muted">${esc(csvName)} · ${csv.rows.length} filas. Esta importación es una copia, no una sincronización en vivo.</p>${select('Importar como','csvKind',kind,{leads:'Contactos del CRM',publications:'Publicaciones del calendario',usage:'Consumo de tokens'})}<div class="mapping-grid">${Object.entries(labels[kind]).map(([key,label])=>{const options=aliases[key]||[key],match=csv.headers.find(h=>options.some(alias=>alias.toLocaleLowerCase()===h.toLocaleLowerCase()))||'';return select(label,`map-${key}`,match,{'':'No importar',...Object.fromEntries(csv.headers.map(h=>[h,h]))});}).join('')}</div><p class="storage-meta">Fecha + Hora se interpretan en Cancún (UTC−05:00). Conservamos ID, Copy, Red, Formato, Archivo, Hashtags y Estado de la hoja. Un aprobado/programado entra en revisión local para que lo confirmes. Para exportar decisiones con comprobación de versión, usa el JSON del script de Google Sheets.</p>`,`${button('Cancelar','close')}<button class="btn primary" type="submit">Importar filas válidas</button>`);$('[name=csvKind]').id='csv-kind';}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function downloadBackup(){try{download(exportBackup(state),`ornat-control-${new Date().toISOString().slice(0,10)}.json`);commit('Exportar respaldo',s=>{s.settings.lastBackupAt=new Date().toISOString();},'Se descargó un archivo JSON con los datos locales.',true);toast('Respaldo descargado. Conserva el archivo en un lugar seguro.');}catch(error){toast(error.message,true);}}
function deleteItem(kind,id,label){if(!confirm(`¿Eliminar ${label}? ${remote?'Esta acción afecta a todo el equipo.':'Esta acción afecta solo a este navegador.'}`))return;if(commit(`Eliminar ${label}`,s=>{s[kind]=s[kind].filter(item=>item.id!==id);})){if($('#dialog').open)$('#dialog').close();}}
function ingestEvents(list,source='integración local'){if(!state.settings.analyticsConsent)return;try{const known=new Set(state.events.map(e=>e.id)),events=list.map(item=>normalizeHeatEvent(item,true)).filter(e=>{if(known.has(e.id))return false;known.add(e.id);return true;});if(!events.length)return;commit('Registrar interacciones',s=>{s.events.push(...events);s.events=s.events.slice(-10000);},`${events.length} eventos reales · ${source}`,true);}catch(error){toast(`Evento descartado: ${error.message}`,true);}}
async function handleImport(file){if(file.size>8*1024*1024)throw new Error('Importa archivos de hasta 8 MB.');const raw=await file.text();if(file.name.toLowerCase().endsWith('.csv')){csv=parseCSV(raw);csvName=file.name;csvDialog();return;}if(!/\.json$/i.test(file.name)&&file.type!=='application/json')throw new Error('Formato no compatible. Importa un archivo .csv o .json.');let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('El archivo no es un JSON válido. Revisa que no esté dañado o incompleto.');}if(parsed?.format==='ornat-control'){latestImport=importBackup(raw);openDialog('backup','Restaurar tu respaldo',`<p>Este archivo contiene ${latestImport.leads.length} contactos, ${latestImport.publications.length} publicaciones y ${latestImport.usage.length} registros de consumo.</p><div class="notice warn">${remote?'<b>Afecta a todo el equipo.</b> Reemplazará los datos del CRM para todas las cuentas de tu organización.':'Reemplazará los datos actuales de este panel.'} Descarga un respaldo primero si quieres conservarlos.</div>`,`${button('Cancelar','close')}<button class="btn primary" type="submit">${remote?'Reemplazar para todo el equipo':'Reemplazar con este respaldo'}</button>`);return;}if(parsed?.format==='ornat-calendar'){const imported=importCalendarSnapshot(raw);latestImport=imported;openDialog('calendar-import','Importar calendario de Sheets',`<p>${imported.posts.length} publicaciones válidas listas para importar.</p><div class="notice">Esta es una copia del calendario, no una conexión en vivo. Los estados aprobados/programados pasan a revisión local. Las decisiones conservan ID y versión para evitar sobrescribir cambios posteriores en la hoja.</div>${imported.warnings.length?`<div class="notice warn">${imported.warnings.map(w=>esc(w)).join('<br>')}</div>`:''}`,`${button('Cancelar','close')}<button class="btn primary" type="submit">Importar copia del calendario</button>`);return;}if(parsed?.format==='ornat-analytics'){if(!state.settings.analyticsConsent)throw new Error('Activa el consentimiento en Mapa de interacción antes de importar eventos.');if(!Array.isArray(parsed.events))throw new Error('El JSON debe contener una lista events.');ingestEvents(parsed.events,'JSON importado');return;}const rows=Array.isArray(parsed)?parsed:parsed.records||parsed.usage;if(!Array.isArray(rows))throw new Error('El JSON necesita un respaldo ORNAT, una lista records/usage de consumo o formato ornat-analytics.');const usage=validateState({...emptyState(),usage:rows.map(row=>({...row,id:uid(),date:row.date||row.timestamp,inputTokens:row.inputTokens??row.input_tokens??row.usage?.input_tokens??row.usage?.prompt_tokens,outputTokens:row.outputTokens??row.output_tokens??row.usage?.output_tokens??row.usage?.completion_tokens,source:'json',reference:row.reference||file.name}))}).usage;commit('Importar consumo JSON',s=>s.usage.push(...usage),`${usage.length} registros · ${file.name}`);}
document.addEventListener('click',event=>{const b=event.target.closest('button,a[data-view]');if(!b)return;if(b.dataset.view){changeView(b.dataset.view);return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;try{if(action==='guest-enter'){ss.set(GUEST_KEY,'1');computeAccess();render();return;}if(action==='guest-exit'){ss.del(GUEST_KEY);computeAccess();render();return;}if(action==='sign-out'){if(remote){Promise.resolve().then(()=>remote.signOut()).catch(()=>{}).finally(()=>location.assign('/cuenta/'));return;}dataLayer?.signOut();return;}if(UR.handleAction(action,b)||crm.handleAction(action,b))return;if(action==='clear-post-filters'){postFilters=defaultPostFilters();renderCalendar();return;}if(action.startsWith('go-')){changeView(action.slice(3));return;}if(action==='close')$('#dialog').close();if(action==='new-post')postDialog();if(action==='edit-post')postDialog(id);if(action==='new-usage')usageDialog();if(action==='month-prev'){month=new Date(month.getFullYear(),month.getMonth()-1,1);renderCalendar();}if(action==='month-next'){month=new Date(month.getFullYear(),month.getMonth()+1,1);renderCalendar();}if(action==='month-today'){month=new Date();renderCalendar();}if(action==='delete-lead')deleteItem('leads',id,'contacto');if(action==='delete-post')deleteItem('publications',id,'publicación');if(action==='delete-usage')deleteItem('usage',id,'registro de consumo');if(action==='post-status'){const post=state.publications.find(p=>p.id===id),next=transitionPublication(post,b.dataset.next);if(next.status==='approved'&&next.calendar){const reviewer=prompt('¿Quién aprueba este contenido? Nombre para el registro de la hoja:');if(!reviewer?.trim())return;next.calendar={...next.calendar,decision:'approve',reviewer:reviewer.trim()};}commit(`Publicación: ${POST_STATUSES[next.status]}`,s=>{s.publications=s.publications.map(p=>p.id===id?next:p);},post.title);}if(action==='connection')openDialog('info',`Conectar ${b.dataset.network}`,`<div class="notice warn">Esta cuenta sigue desconectada.</div><p class="muted">Para mostrar mensajes reales se necesita una integración OAuth oficial, permisos de la cuenta y un backend que proteja los tokens. Esta prueba gratuita no almacena contraseñas ni claves privadas.</p><p class="muted">Mientras se prepara la conexión, puedes llevar tus contactos y notas en el CRM e importar tus datos por CSV.</p>`,button('Entendido','close','primary'));if(action==='calendar-reviews'){if(!state.settings.calendarSource?.spreadsheetId||!state.settings.calendarSource?.sheetId){toast('Primero importa una copia del calendario de Google Sheets (JSON del script). Las decisiones se exportan sobre esa copia.',true);return;}const payload=calendarReviews(state.publications,state.settings.calendarSource);download(JSON.stringify(payload,null,2),'ornat-calendar-review.json');commit('Exportar decisiones de calendario',()=>{},`${payload.reviews.length} decisiones locales`,true);toast('Decisiones descargadas. Impórtalas en tu hoja mediante el script privado.');}if(action==='reject-post'){const post=state.publications.find(p=>p.id===id),reviewer=prompt('¿Quién revisó este contenido? Nombre para el registro de la hoja:');if(!reviewer?.trim())return;commit('Rechazar publicación en revisión',s=>{const p=s.publications.find(p=>p.id===id);p.status='draft';p.approvedAt='';if(p.calendar)p.calendar={...p.calendar,decision:'reject',reviewer:reviewer.trim()};},post.title);}if(action==='backup')downloadBackup();if(action==='import'){$('#import-file').value='';$('#import-file').click();}if(action==='save-sheet'){const value=$('#sheet-url').value.trim();commit('Actualizar enlace de Google Sheets',s=>{s.settings.sheetUrl=value;});}if(action==='reset'){if(denyReadOnly())return;if(confirm(remote?'¿Borrar los datos del CRM para todo el equipo? Afecta a todas las cuentas de tu organización y no se puede deshacer. Descarga antes un respaldo.':'¿Borrar los datos de este panel? Descarga antes un respaldo.')){state=store.replace(emptyState(),remote?'Borrar datos del equipo':'Borrar datos locales');render();toast('Panel vacío. Se conserva solo el registro de esta restauración.');}}if(action==='clear-events'){if(confirm('¿Eliminar los eventos de interacción guardados?'))commit('Eliminar eventos de interacción',s=>s.events=[]);}if(action==='refresh-heat'){consumeStoredEvents();state=store.get();renderHeatmap();}}catch(error){toast(error.message,true);}});
$('#dialog-shell').addEventListener('submit',event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),kind=$('#dialog').dataset.kind,id=$('#dialog').dataset.id;try{let saved=false;const handled=crm.handleSubmit(kind,values,id);if(handled!==undefined){if(handled)$('#dialog').close();return;}if(kind==='post'){const old=state.publications.find(p=>p.id===id),post={...old,...values,id:id||uid(),status:'draft',approvedAt:'',...(old?.calendar?{calendar:{...old.calendar,decision:'',reviewer:''}}:{}),scheduledAt:values.scheduledAt?new Date(values.scheduledAt).toISOString():'',createdAt:old?.createdAt||new Date().toISOString(),source:old?.source||'manual'};saved=commit(old?'Editar publicación como borrador':'Crear borrador',s=>{if(old)s.publications=s.publications.map(p=>p.id===id?post:p);else s.publications.push(post);},post.title);}if(kind==='usage'){const usage={...values,id:uid(),date:new Date(values.date).toISOString(),source:'manual'};saved=commit('Registrar consumo declarado',s=>s.usage.unshift(usage),`${values.model} · ${values.scope} · ${values.reference}`);}if(kind==='csv'){const mapping=Object.fromEntries(Object.entries(values).filter(([k])=>k.startsWith('map-')).map(([k,v])=>[k.slice(4),v])),rows=mapCSV(csv,mapping,values.csvKind);saved=values.csvKind==='leads'?crm.importLeads(rows,csvName):commit('Importar CSV',s=>s[values.csvKind].push(...rows),`${rows.length} registros · ${csvName}`);}if(kind==='calendar-import'){const imported=latestImport;saved=commit('Importar copia de calendario',s=>{const existing=new Set(imported.posts.map(p=>p.calendar.id));s.publications=s.publications.filter(p=>!(p.calendar?.spreadsheetId===imported.source.spreadsheetId&&p.calendar?.sheetId===imported.source.sheetId&&existing.has(p.calendar.id)));s.publications.push(...imported.posts);s.settings.calendarSource=imported.source;},`${imported.posts.length} filas · ${imported.warnings.length} advertencias`);}if(kind==='backup'){if(denyReadOnly())return;if(remote&&!confirm('¿Reemplazar el CRM de todo el equipo con este respaldo? Todas las cuentas de tu organización verán el cambio.'))return;state=store.replace(latestImport);render();toast(remote?'Respaldo restaurado para todo el equipo.':'Respaldo restaurado en este navegador.');saved=true;}if(saved)$('#dialog').close();}catch(error){toast(error.message,true);}});
function postFilterEvent(el){const map={'pf-q':'q','pf-status':'status','pf-channel':'channel','pf-month':'month','pf-dated':'dated','pf-sort':'sort'};if(!map[el.id])return false;postFilters={...postFilters,[map[el.id]]:el.value};$('#post-results').innerHTML=postResults();return true;}
document.addEventListener('input',event=>{if(crm.handleInput(event.target))return;if(event.target.id==='pf-q')postFilterEvent(event.target);});
document.addEventListener('keydown',event=>{crm.handleKeydown(event);});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='scope-pick'){ss.set(SCOPE_KEY,el.value);computeAccess();scopeMemo={state:null,key:'',val:null};render();return;}if(UR.handleChange(el)||crm.handleChange(el))return;if(postFilterEvent(el))return;if(el.id==='csv-kind')csvDialog();if(el.id==='heat-group'){selectedHeat=el.value;selectedViewport='';renderHeatmap();}if(el.id==='heat-viewport'){selectedViewport=el.value;renderHeatmap();}if(el.id==='analytics-consent'){const enabled=el.checked;commit(enabled?'Activar consentimiento de analítica':'Detener captura de analítica',s=>s.settings.analyticsConsent=enabled,'Solo eventos técnicos en este navegador.')||(el.checked=!enabled);}if(el.id==='import-file'&&el.files[0]){const file=el.files[0];el.value='';handleImport(file).catch(error=>toast(error.message,true));}});
function consumeStoredEvents(){if(!state.settings.analyticsConsent)return;try{const raw=localStorage.getItem('ornat-analytics-events');if(!raw)return;const parsed=JSON.parse(raw);if(Array.isArray(parsed))ingestEvents(parsed,'captura local de páginas ORNAT');}catch(error){toast('No se pudieron leer los eventos locales: '+error.message,true);}}
window.addEventListener('message',event=>{if(event.origin!==location.origin||!event.source||event.data?.channel!=='ornat-control'||event.data.type!=='analytics-event')return;ingestEvents([event.data.event],'postMessage del mismo origen');});
window.addEventListener('storage',event=>{if(event.key==='ornat-analytics-events')consumeStoredEvents();if(event.key==='ornat-control-v1'){try{state=store.get();render();}catch(error){toast(error.message,true);}}});
const ctx={getState:()=>scoped(),raw:()=>state,commit,toast,openDialog,closeDialog:()=>$('#dialog').close(),empty,stamp,download,goView:changeView,esc,rerender:()=>render(),refreshFicha:()=>crm.refreshFicha(),refreshBadges,access:()=>access,user:()=>access.user,owners,defaultOwner:()=>access.scope==='mine'||access.user.role==='sales'?access.user.name:'',scoreOf:id=>scoreMap.get(id),scoreVersion:()=>scoreVer,properties:()=>props,reloadProps,canProp,data:()=>dataLayer,audit:auditLog,pipelines:()=>state.settings.pipelines,intakePending:()=>{try{return dataLayer?.intake.size()||0;}catch{return 0;}}};
async function mountSession(){
 const slot=$('#session-slot');if(!slot)return;
 try{await import('../shared/session-bar.js');if(customElements.get('ornat-session')){slot.innerHTML='<ornat-session current="crm"></ornat-session>';return;}}catch{}
 const u=access.user;slot.innerHTML=access.mode==='user'?`<span class="session-fallback"><b>${esc(u.name)}</b> · ${esc(access.role)} <button type="button" class="btn small" data-action="sign-out">Salir</button></span>`:`<a class="btn small" href="${loginURL()}">Entrar</a>`;}
async function boot(){
 try{({remote}=await import('../shared/remote-boot.js'));}catch{remote=null;}
 if(remote){
  if(!remote.requireAuth())return;
  remoteChrome();$('#save-status').textContent='Conectando…';
  try{adapter=await remote.mirror(CRM_SPEC);}catch(error){$('#content').innerHTML=`<div class="notice warn">No se pudo conectar con la base de datos del equipo: ${esc(error.message)} Recarga la página para reintentar.</div>`;$('#save-status').textContent='Sin conexión';return;}
 }
 try{store=createStore(adapter||undefined);state=store.get();}catch(error){$('#content').innerHTML=`<div class="notice warn">${esc(error.message)}</div>`;$('#save-status').textContent='Almacenamiento no disponible';toast(error.message,true);return;}
 try{const mod=await import('../shared/data.js');dataLayer=mod.data();}catch{dataLayer=null;}
 computeAccess();reloadProps();
 crm.init(ctx);UR.init(ctx);
 render();processIntake();consumeStoredEvents();mountSession();
 dataLayer?.subscribe(topic=>{if(topic==='audit')return;if(topic==='intake'||topic==='all'){processIntake();}if(topic==='session'||topic==='all'||topic==='users'){computeAccess();scopeMemo={state:null,key:'',val:null};mountSession();processIntake();render();}if(topic==='properties'||topic==='all'){reloadProps();render();crm.refreshFicha();}});
 if(globalThis.BroadcastChannel){const channel=new BroadcastChannel('ornat-control-analytics');channel.onmessage=event=>{const data=event.data;if(data?.channel==='ornat-control'&&data.type==='analytics-event')ingestEvents([data.event],'BroadcastChannel del mismo origen');};}
 window.addEventListener('afterprint',()=>{delete document.body.dataset.printing;});
 if(remote){setInterval(syncStatus,1000);window.addEventListener('ornat:sync',event=>{if(!event.detail||event.detail.key===CRM_SPEC.key)syncStatus();});window.addEventListener('storage',event=>{if(event.key==='ornat-data-v1')processIntake();});window.addEventListener('focus',()=>processIntake());}
 if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
}
boot();
